-- Parthvi Exim: import ONCE into an EMPTY database selected in phpMyAdmin.
-- Contains existing data and password hashes. No DROP, no reset, no CREATE DATABASE.
SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE settings (id INT UNSIGNED PRIMARY KEY, data LONGTEXT NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE pages (slug VARCHAR(100) PRIMARY KEY, data LONGTEXT NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE records (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type VARCHAR(30) NOT NULL, data LONGTEXT NOT NULL, position INT NOT NULL DEFAULT 0, published TINYINT NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1, INDEX records_listing (type,published,position,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE admins (id INT UNSIGNED PRIMARY KEY, email VARCHAR(254) NOT NULL, password VARCHAR(255) NOT NULL, version INT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE inquiries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, data LONGTEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'New', created_at DATETIME NOT NULL, INDEX inquiries_status (status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE rate_limits (`key` VARCHAR(100) PRIMARY KEY, attempts INT UNSIGNED NOT NULL DEFAULT 0, expires BIGINT UNSIGNED NOT NULL, INDEX rate_expiry (expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE activity (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, message TEXT NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
COMMIT;
ALTER TABLE `records` AUTO_INCREMENT = 17;
ALTER TABLE `inquiries` AUTO_INCREMENT = 2;
ALTER TABLE `activity` AUTO_INCREMENT = 3;
